// Validate JWT and extract claims
const body = $input.item.json.body;
const headers = $input.item.json.headers;

// Check Authorization header
if (!headers.authorization) {
  throw new Error('Missing Authorization header');
}

const token = headers.authorization.replace('Bearer ', '');

// Extract payload (in production, verify signature)
const claims = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());

// Validate required fields
if (!body.org_id || !body.thread_id || !body.message) {
  throw new Error('Missing required fields: org_id, thread_id, message');
}

// Check org access
if (claims.org_id && claims.org_id !== body.org_id) {
  throw new Error('Access denied: org_id mismatch');
}

return {
  json: {
    org_id: body.org_id,
    thread_id: body.thread_id,
    user_id: body.user_id || claims.user_id,
    message: body.message,
    files: body.files || [],
    metadata: body.metadata || {},
    validated: true
  }
};

// Resolve database credentials based on org mode
const orgData = $input.item.json;
const inputData = $('Validate JWT').item.json;

if (!orgData || orgData.length === 0) {
  throw new Error('Organization not found or not active');
}

const org = Array.isArray(orgData) ? orgData[0] : orgData;

let credentials = {};

if (org.mode === 'saas') {
  // Use default SaaS credentials
  credentials = {
    mode: 'saas',
    credential_id: 'saas-postgres',
    location: 'cloud'
  };
} else if (org.mode === 'on_prem') {
  // Flag to fetch on-prem credentials
  credentials = {
    mode: 'on_prem',
    org_id: org.id,
    needs_lookup: true
  };
} else {
  throw new Error('Unknown organization mode: ' + org.mode);
}

return {
  json: {
    ...inputData,
    org_name: org.name,
    org_mode: org.mode,
    credentials: credentials
  }
};

// Decrypt on-prem credentials (simplified - in production use proper decryption)
const credsData = $input.item.json;
const prevData = $('Resolve Org Credentials').item.json;

if (!credsData || credsData.length === 0) {
  throw new Error('On-prem credentials not configured');
}

const creds = Array.isArray(credsData) ? credsData[0] : credsData;

// In production, decrypt these fields using encryption key
// For now, marking that decryption is needed
prevData.credentials = {
  mode: 'on_prem',
  location: 'on_prem',
  encrypted: true,
  host: creds.host_encrypted,
  port: creds.port,
  database: creds.database_name_encrypted,
  username: creds.username_encrypted,
  password: creds.password_encrypted
};

return { json: prevData };

// Merge all context data
const mainData = $('Merge Paths').item.json;
const history = $('Load Chat History').all().map(item => item.json);
const files = $('Load Process Files').all().map(item => item.json);
const timeline = $('Load Timeline').all().map(item => item.json);

// Build context for LLM
const context = {
  thread_id: mainData.thread_id,
  org_id: mainData.org_id,
  org_name: mainData.org_name,
  user_message: mainData.message,
  history: history.reverse(), // Oldest first
  files: files,
  timeline: timeline,
  files_count: files.length,
  timeline_latest: timeline[0] || null
};

return { json: context };

// Build prompt for LLM with context
const ctx = $input.item.json;

// Build system prompt
const systemPrompt = `Você é um assistente especializado em processos ambientais no Brasil. 
Você ajuda usuários a organizar documentos e entender requisitos das Instruções Normativas (INs) municipais.

Contexto do processo:
- Thread ID: ${ctx.thread_id}
- Organização: ${ctx.org_name}
- Arquivos anexados: ${ctx.files_count}
- Última atualização da timeline: ${ctx.timeline_latest ? ctx.timeline_latest.title : 'Nenhuma'}

Arquivos disponíveis:
${ctx.files.map(f => `- ${f.filename} (${f.category || 'sem categoria'})`).join('\n')}

Responda de forma objetiva, prática e com checklist quando apropriado.`;

// Build conversation history
const messages = [
  { role: 'system', content: systemPrompt }
];

// Add history (last 10 messages)
const recentHistory = ctx.history.slice(-10);
for (const msg of recentHistory) {
  messages.push({
    role: msg.role === 'user' ? 'user' : 'assistant',
    content: msg.content
  });
}

// Add current user message
messages.push({
  role: 'user',
  content: ctx.user_message
});

return {
  json: {
    messages: messages,
    max_tokens: 800,
    temperature: 0.7,
    thread_context: ctx
  }
};

// Format response for frontend
const aiResponse = $input.item.json.response || $input.item.json.text || '';
const ctx = $('Build LLM Prompt').item.json.thread_context;

// Extract checklist if present (simple parsing)
const hasChecklist = aiResponse.includes('- [ ]') || aiResponse.includes('- [x]');

// Build response
const response = {
  thread_id: ctx.thread_id,
  message: aiResponse,
  has_checklist: hasChecklist,
  files_referenced: ctx.files_count,
  timeline_updated: false,
  metadata: {
    tokens_used: $input.item.json.usage?.total_tokens || 0,
    model: 'gemini-1.5-flash',
    timestamp: new Date().toISOString()
  }
};

return { json: response };

// Error handler
const error = $input.item.json.error || 'Unknown error';
const orgId = $('Validate JWT')?.item?.json?.org_id || 0;

return {
  json: {
    error: true,
    message: error.message || error,
    thread_id: $('Validate JWT')?.item?.json?.thread_id || null,
    org_id: orgId
  }
};
